import{SAMPLE_WORDS}from'./sample.js';
import{REQUIRED_METHODS,COLOUR_REWARDS,EYE_COLOURS,wordProgress,syncEgg,shuffle,canUseColour,recordSchoolTest,careForBaby}from'./spelling.js';
import{MONSTER_VOICES,monsterUtterance}from'./voice.js';
import{localDay,cleanWords}from'./learning.js';
import{suggestWordList}from'./meanings.js';
import{calmUtterance,femaleEnglishVoices,chooseCalmVoice}from'./voice.js';
import{METHODS,WARDROBE,BABIES,freshProfile,parseWeeklyWords,setWeek,nextTestDay,formatDay,addDays,orderedWords,recordWord,completeWord,rewardAvailable,chooseClothes,equip,itemById,eggProgress,hatchEgg,choicesFor,gapFor,markTest}from'./spelling.js';
import{palMarkup,mountMonsters,COLOURS}from'./monster.js';
import{bindPalInteractions,stopPalInteraction,setSound,soundEffect}from'./pal-interaction.js';

const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='practimals-spelling-v4';
let state;try{state=JSON.parse(localStorage.getItem(KEY));}catch{}
if(!state||![4,5].includes(state.version)||!state.profiles?.length)state={version:4,active:'one',sound:true,profiles:[freshProfile('one','Child 1',7),freshProfile('two','Child 2',10)]};
if(state.version!==5){for(const pr of state.profiles){pr.totalGames=pr.week?.games.length||0;pr.voiceStyle='bubbles';pr.eyeColour='violet';pr.schoolResults??=[];if(!pr.palName||pr.palName==='Your pal')pr.palName='Bobble';if(pr.words.length&&pr.words.map(w=>w.word).join()!==SAMPLE_WORDS.map(w=>w.word).join()){(pr.archivedLists??=[]).push({words:pr.words,testDate:pr.week?.testDate});}setWeek(pr,SAMPLE_WORDS.map(w=>({...w})),pr.week?.testDate||nextTestDay(),{newWeek:pr.words.map(w=>w.word).join()!==SAMPLE_WORDS.map(w=>w.word).join()});syncEgg(pr);}state.version=5;localStorage.setItem(KEY,JSON.stringify(state));}
let hatchScene=null,demoBaby=null,lastStart=null;
let pendingQuestion=null,speechRun=0;
let view='home',selectedWord=null,session=null,test=null,parentOpen=false,parentMessage='',chosenBaby=null,cleanPal=null,cleanModels=null,drawing=false,canvasDirty=false,creativeWord=null,photoUrl='',toastTimer;
const p=()=>state.profiles.find(x=>x.id===state.active)||state.profiles[0];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{notify('This browser cannot save more. New progress will last only for this session.');}}
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4300);}
function speak(text,{quiet=false}={}){if(!('speechSynthesis'in window)){if(!quiet)notify('Ask a grown-up to read the word; speech is unavailable here.');return false;}const token=++speechRun;speechSynthesis.cancel();document.dispatchEvent(new CustomEvent('pal-speaking',{detail:false}));const utterance=monsterUtterance(text,speechSynthesis.getVoices(),state.voiceURI,p().voiceStyle,SpeechSynthesisUtterance);if(!utterance){if(!quiet)notify('Choose or enable a female English voice in Grown-ups or the device’s speech settings.');return false;}utterance.onstart=()=>{if(token===speechRun)document.dispatchEvent(new CustomEvent('pal-speaking',{detail:true}));};const end=()=>{if(token===speechRun)document.dispatchEvent(new CustomEvent('pal-speaking',{detail:false}));};utterance.onend=end;utterance.onerror=e=>{end();if(!quiet&&!['canceled','interrupted'].includes(e.error))notify('That voice could not play. Check the device’s speech settings.');};speechSynthesis.speak(utterance);return true;}
function questionText(){if(view==='test'&&test&&!test.result)return 'Word '+(test.index+1)+'. Can you spell '+test.items[test.index].word+' for me?';if(!session||session.finished)return null;const w=view==='creative'?p().words.find(x=>x.word===creativeWord):session.items[session.index];if(!w)return null;return {study:'Our word is '+w.word+'. Look at it and say it with me. Tap cover when you are ready.',listen:'Can you spell '+w.word+' for me?',build:'Can you build '+w.word+' using these letters?',letters:'Some letters in '+w.word+' are hiding. Can you spell the whole word?',gap:'Can you find the missing word? '+gapFor(w).replaceAll('_____','blank'),meaning:'Which of your weekly words means '+(w.meaning||'the word your grown-up describes')+'?',sentence:'Can you use '+w.word+' in your own sentence?',draw:'What picture could help us remember '+w.word+'?'}[session.method];}
function speakPending(){if(pendingQuestion&&state.sound&&state.spokenQuestions!==false&&speak(pendingQuestion,{quiet:true}))pendingQuestion=null;}

function go(next){if(hatchScene)hatchScene=null;if(next!=='egg')demoBaby=null;pendingQuestion=null;document.dispatchEvent(new CustomEvent('pal-speaking',{detail:false}));if('speechSynthesis'in window)speechSynthesis.cancel();view=next;if(next!=='parents')parentOpen=false;session=null;test=null;render();scrollTo({top:0,behavior:'smooth'});}
function header(){return `<header><a class="brand" href="#" data-go="home"><span class="brand-symbol monster-logo" aria-hidden="true"><i></i><i></i><b>⌣</b></span>practimals<small>little practice, big confidence</small></a><nav aria-label="Main navigation">${[['home','This week'],['pal','My pal'],['egg','My egg']].map(([key,label])=>`<button class="nav-link ${view===key?'active':''}" data-go="${key}">${label}</button>`).join('')}</nav><div class="header-tools"><button class="sound-button" id="sound" aria-label="${state.sound?'Mute':'Enable'} creature sounds">♫ ${state.sound?'On':'Off'}</button><button class="grownups" data-go="parents">Grown-ups ↗</button></div></header>`;}
function weekLine(){return p().week?`<div class="week-line"><span>${esc(p().name)}’s weekly spellings</span><strong>${p().words.length} words</strong><span>School test: ${formatDay(p().week.testDate)}</span></div>`:'';}
function render(){cleanPal?.();cleanModels?.();stopPalInteraction();drawing=false;const pages={home:homePage,pal:palPage,egg:eggPage,parents:parentsPage,game:gamePage,creative:creativePage,test:testPage,scrapbook:scrapbookPage,hatching:hatchingPage};$('#app').innerHTML=header()+`<main>${view!=='parents'?weekLine():''}${(pages[view]||homePage)()}</main><footer>Only this week’s words. Plenty of ways to practise.<span>Made for ages 5–10</span></footer>`;setSound(state.sound);bindCommon();cleanPal=bindPalInteractions();cleanModels=mountMonsters();if(view==='game')bindGame();if(view==='creative')bindCreative();if(view==='parents')bindParents();if(view==='test')bindTest();bindV5();document.querySelectorAll('input:not([type]),input[type=text],textarea').forEach(el=>{el.setAttribute('autocorrect','off');el.setAttribute('autocapitalize','none');el.setAttribute('autocomplete','off');el.setAttribute('spellcheck','false');el.setAttribute('data-gramm','false');el.setAttribute('data-enable-grammarly','false');});speakPending();}
function profilePicker(){return `<label class="profile-picker">Practising as<select id="profile">${state.profiles.map(x=>`<option value="${x.id}" ${x.id===p().id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`;}
function palCard(){return `<aside class="companion-card"><div class="companion-name"><span>YOUR PRACTICE PAL</span><h2>${esc(p().palName)}</h2></div>${palMarkup(p())}<p class="touch-tip">Tap to say hello · Double-tap to tickle<br>Hold for a happy purr</p>${rewardSummary()}<button class="text-button" data-go="pal">Make your pal your own →</button></aside>`;}
function homePage(){const pr=p(),progress=pr.week?.progress||{},practised=pr.words.filter(w=>wordProgress(pr,w.word)===6).length;return `<section class="page-intro"><div><span class="eyebrow">A LITTLE PRACTICE. YOUR VERY OWN PAL.</span><h1>This week’s spellings.</h1><p>See your words. Choose a way to practise. Have a little go.</p></div>${profilePicker()}</section><div class="home-layout"><div class="learning-column">${pr.words.length?`<section class="word-panel"><div class="section-heading"><div><h2>Your ${pr.words.length} words</h2><p>${practised} of ${pr.words.length} words complete · all six challenges to turn green</p></div><button class="small-button" id="hear-all">♫ Hear my list</button></div><div class="word-grid">${pr.words.map((w,i)=>`<button class="word-chip ${wordProgress(pr,w.word)===6?'tried':''} ${selectedWord===w.word?'selected':''}" data-word="${esc(w.word)}"><small>${String(i+1).padStart(2,'0')}</small><strong>${esc(w.word)}</strong><span class="word-count" aria-label="${wordProgress(pr,w.word)} of six challenges complete">${wordProgress(pr,w.word)===6?'✓':wordProgress(pr,w.word)+'/6'}</span><span class="word-dots" aria-hidden="true">${REQUIRED_METHODS.map(method=>`<i class="${progress[w.word]?.passed?.includes(method)?'done':''}"></i>`).join('')}</span></button>`).join('')}</div><p class="word-key">Six little lights per word: look & cover · hear · build · letters · sentence gap · meaning. Pictures and your own sentences are bonus practice.</p>${selectedWord?wordDetail(pr.words.find(w=>w.word===selectedWord)):''}</section><section class="practice-section"><div class="section-heading"><div><h2>How shall we practise?</h2><p>Every activity uses your weekly list.</p></div></div><div class="method-grid">${Object.entries(METHODS).map(([key,m])=>`<button class="method-card mode-${key}" data-method="${key}"><span class="method-icon">${methodArt(key)}</span><div><h3>${m.title}</h3><p>${m.description}</p><small>${['draw','sentence'].includes(key)?'Choose a word from your list':`All ${pr.words.length} weekly words · pause and come back`}</small></div><span class="method-arrow">→</span></button>`).join('')}</div></section><section class="test-banner"><span class="test-icon">✓</span><div><h2>Try the whole list</h2><p>One practice test. All ${pr.words.length} spellings. No rush.</p></div><button class="primary" id="start-test">Take a practice test →</button></section>`:`<section class="empty-card"><span class="empty-icon">Aa</span><h2>Let’s add your real spelling list.</h2><p>A grown-up can type this week’s 10–20 words and set the test date. Then every game will use those words.</p><button class="primary" data-go="parents">Add this week’s spellings →</button></section>`}</div>${palCard()}</div>`;}
function wordDetail(w){if(!w)return'';return `<div class="word-detail"><div><span class="eyebrow">LET’S UNDERSTAND IT</span><h3>${esc(w.word)}</h3><div class="word-checklist">${REQUIRED_METHODS.map(m=>`<span class="${p().week.progress[w.word]?.passed?.includes(m)?'done':''}">${p().week.progress[w.word]?.passed?.includes(m)?'✓':'○'} ${METHODS[m].title}</span>`).join('')}</div><p>${esc(w.meaning||'Ask a grown-up to add a simple meaning for this word.')}</p>${w.sentence?`<p class="example">${esc(w.sentence)}</p>`:''}</div><button class="secondary" data-hear="${esc(w.word)}">♫ Hear it</button></div>`;}
function rewardSummary(){const count=p().totalGames||0;return `<div class="reward-summary"><strong>${count} practice ${count===1?'game':'games'} · growing your collection</strong><div>${Object.entries(WARDROBE).map(([key,slot])=>`<span class="${count>=slot.after?'unlocked':''}">${{hat:'♧',coat:'♢',shoes:'⌁',glasses:'◎',gloves:'✋',earrings:'✧'}[key]} ${key}<small>${count>=slot.after?'Unlocked':`After ${slot.after} ${slot.after===1?'game':'games'}`}</small></span>`).join('')}</div></div>`;}
function palPage(){const pr=p();return `<section class="page-intro"><div><span class="eyebrow">ALL THE PERSONALITY. NONE OF THE RUSH.</span><h1>Your very own Practimal.</h1><p>Start with a little alien. Give it a name. Help it grow a wardrobe.</p></div></section><div class="pal-layout">${palCard()}<section class="customise-card"><label class="field-label" for="pal-name">What shall we call your pal?</label><div class="inline-input"><input id="pal-name" maxlength="24" value="${esc(pr.palName)}"><button class="secondary" id="save-pal-name">Save name</button></div><fieldset><legend>Choose a little monster</legend><div class="shape-choices">${[['bobble','Bobble','Two eyes, curious feelers'],['blip','Blip','Three eyes, one wiggly antenna'],['wiggle','Wiggle','Tall, floppy and a little odd']].map(([id,label,desc])=>`<button class="choice ${pr.species===id?'selected':''}" data-shape="${id}" aria-pressed="${pr.species===id}"><strong>${label}</strong><small>${desc}</small></button>`).join('')}</div></fieldset><fieldset><legend>A colour that feels like you</legend><div class="colour-choices">${Object.keys(COLOUR_REWARDS).map(key=>`<div class="colour-option"><button class="swatch ${pr.colour===key?'selected':''}" style="--colour:${key==='rainbow'?'linear-gradient(135deg,#ff899d,#f4cf72,#6ed9b6,#83b8f6,#bd8afa)':COLOURS[key]}" data-colour="${key}" title="${key} · ${COLOUR_REWARDS[key]} games" aria-label="${key}${canUseColour(pr,key)?'':', unlock at '+COLOUR_REWARDS[key]+' games'}" ${canUseColour(pr,key)?'':'disabled'} aria-pressed="${pr.colour===key}">${canUseColour(pr,key)?pr.colour===key?'✓':'':'🔒'}</button><small>${key}</small><span>${canUseColour(pr,key)?'Yours':COLOUR_REWARDS[key]+' games'}</span></div>`).join('')}</div></fieldset><fieldset><legend>Those lovely eyes</legend><div class="colour-choices">${Object.entries(EYE_COLOURS).map(([key,colour])=>`<button class="swatch ${pr.eyeColour===key?'selected':''}" style="--colour:${colour}" data-eyes="${key}" aria-label="${key} eyes" aria-pressed="${pr.eyeColour===key}">${pr.eyeColour===key?'✓':''}</button>`).join('')}</div></fieldset><fieldset><legend>Choose my monster voice</legend><div class="shape-choices">${Object.entries(MONSTER_VOICES).map(([key,v])=>`<button class="choice ${pr.voiceStyle===key?'selected':''}" data-voice-style="${key}" aria-pressed="${pr.voiceStyle===key}"><strong>♫ ${v.name}</strong><small>${v.description} · tap to hear</small></button>`).join('')}</div><p class="hint">Three playful voice styles using your tablet’s English speech voice. The sound varies between devices.</p></fieldset><div class="wardrobe-heading"><h2>Your growing wardrobe</h2><p>Keep practising to earn hats, coats, shoes, glasses, gloves and earrings. New colours unlock too — rainbow at 24 games!</p></div>${Object.entries(WARDROBE).map(([category,slot])=>`<fieldset class="wardrobe-slot"><legend>${category[0].toUpperCase()+category.slice(1)}</legend>${rewardAvailable(pr,category)?`<p class="reward-ready">You’ve earned a choice! Pick your ${category}.</p><div class="clothing-choices">${slot.items.map(item=>`<button class="clothes-choice" data-claim="${item.id}" data-category="${category}"><span class="clothes-icon ${category}" style="--item:${item.colour}">${{hat:'♧',coat:'♢',shoes:'⌁',glasses:'◎',gloves:'✋',earrings:'✧'}[category]}</span><strong>${item.label}</strong><small>Choose this</small></button>`).join('')}</div>`:!pr.items.some(id=>slot.items.some(x=>x.id===id))?`<p class="locked-message">${pr.week?.claimed[category]?'Your choice is in the wardrobe.':`Play ${Math.max(0,slot.after-(pr.totalGames||0))} more ${slot.after-(pr.totalGames||0)===1?'game':'games'} to choose ${slot.title.toLowerCase()}.`}</p>`:''}<div class="owned-items"><button class="small-button ${!pr.wearing[category]?'wearing':''}" data-wear="none" data-category="${category}">No ${category}</button>${slot.items.filter(x=>pr.items.includes(x.id)).map(item=>`<button class="small-button ${pr.wearing[category]===item.id?'wearing':''}" data-wear="${item.id}" data-category="${category}">${item.label}${pr.wearing[category]===item.id?' ✓':''}</button>`).join('')}</div></fieldset>`).join('')}<p class="hint">Clothes you’ve earned stay yours when the next spelling week starts. Repeating a completed game on the same day is welcome, but counts once for wardrobe rewards.</p></section></div>`;}
function eggSVG(egg){const {stage}=eggProgress(egg),cracks=['M112 93 132 119 119 146 143 170 134 191','M183 75 166 104 187 123 176 149','M76 172 103 184 91 211 121 226','M205 177 181 196 199 223 166 240'];return `<svg viewBox="0 0 280 330" class="egg-illustration stage-${stage}" role="img" aria-label="Egg, hatch stage ${stage} of 5"><defs><radialGradient id="egg-shell" cx=".3" cy=".2"><stop stop-color="#e0c6ff"/><stop offset=".6" stop-color="#e3d6f2"/><stop offset="1" stop-color="#bba4d7"/></radialGradient></defs><ellipse cx="140" cy="300" rx="85" ry="15" fill="#a992ba24"/><path d="M140 30C95 30 43 151 47 210c4 63 44 83 93 83s89-20 93-83C237 151 185 30 140 30Z" fill="url(#egg-shell)" stroke="#b7a1ce" stroke-width="2"/>${[[89,136,12],[174,100,9],[185,214,17],[102,236,10],[144,179,14],[72,191,7]].map(([x,y,r])=>`<ellipse cx="${x}" cy="${y}" rx="${r}" ry="${r*.8}" fill="#b598d35c"/>`).join('')}${cracks.slice(0,stage).map(d=>`<path d="${d}" fill="none" stroke="#806294" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`).join('')}${stage>=4?'<path d="M115 182q25-15 49 0" stroke="#fff3ba" stroke-width="6" fill="none" class="egg-glow"/>':''}</svg>`;}
function eggPage(){const pr=p(),egg=pr.eggs.find(x=>x.id===pr.week?.eggId),latest=demoBaby||pr.babies.find(x=>x.id===chosenBaby)||pr.babies.at(-1),baby=latest?BABIES.find(x=>x.id===latest.babyId):null,ep=egg?eggProgress(egg):null;return `<section class="page-intro"><div><span class="eyebrow">PRACTICE GROWS A LITTLE FAMILY</span><h1>Your egg & nursery.</h1><p>Six challenges for every word. Every green word brings your baby closer.</p></div><button class="secondary" id="demo-hatch">✧ Preview a hatch</button></section>${demoBaby?'<div class="demo-notice">Hatch preview — no progress or real babies have been changed. <button class="small-button" id="close-demo">Close preview</button></div>':''}${egg?`<section class="egg-card"><div class="egg-stage">${egg.hatched?'<span class="hatched-shell">✧</span>':eggSVG(egg)}</div><div><span class="eyebrow">THIS WEEK’S EGG</span><h2>${egg.hatched?'A new little friend!':ep.ready?'Someone is ready to say hello!':'A little more practice. A little more wiggle.'}</h2><p>${egg.hatched?'Your baby lives in the nursery below. A new spelling week brings a new egg.':ep.steps+' of '+ep.total+' challenge lights collected. Complete all six challenges for every word to hatch this egg.'}</p><progress max="${ep.total||1}" value="${ep.steps}" aria-label="Egg practice progress"></progress><p>No timer. Take the time you need.</p>${!egg.hatched&&ep.ready?`<button class="primary" data-hatch="${egg.id}">Let’s hatch it →</button>`:'<button class="secondary" data-go="home">Back to my spellings →</button>'}</div></section>`:''}${pr.eggs.filter(e=>e.id!==egg?.id&&!e.hatched&&eggProgress(e).ready).map(e=>`<p class="past-eggs"><button class="secondary" data-hatch="${e.id}">Hatch your completed egg from ${formatDay(e.testDate)} →</button></p>`).join('')}<section class="baby-collection"><div class="section-heading"><div><h2>Your little family · ${pr.babies.length}</h2><p>A cosy place to play, cuddle and rest. Babies never lose happiness while you’re away.</p></div></div>${latest&&baby?`<div class="baby-layout"><div class="baby-display ${latest.care?.asleep?'sleeping':''}">${palMarkup({...baby,palName:latest.name,wearing:{},asleep:latest.care?.asleep},{baby:true})}<h3>${esc(latest.name)} ${demoBaby?'· preview':''}</h3><span class="rarity">${baby.rarity}</span><p class="care-status" role="status">${latest.care?.asleep?'Snuggled up in the cot. Zzz…':'Ready for a cuddle or a little play.'}</p>${latest.care?.asleep?'<div class="baby-cot" aria-hidden="true">☾ <span>│ │ │ │ │</span></div>':''}<div class="baby-care"><button class="secondary" data-care="feed" ${latest.care?.asleep?'disabled':''}>🍓 Feed a berry</button><button class="secondary" data-care="cuddle">♥ Cuddle</button><button class="secondary" data-care="cot">${latest.care?.asleep?'☀ Wake up':'☾ Into the cot'}</button><button class="secondary" data-teach-baby>♫ Teach a weekly word</button></div><p class="hint">${latest.learnedWords?.length?esc(latest.name)+' has learned '+latest.learnedWords.length+(latest.learnedWords.length===1?' word':' words')+' with you! ' :''}Care is for fun. Spelling practice earns your customisations.</p></div><div class="baby-list">${pr.babies.map(b=>{const spec=BABIES.find(x=>x.id===b.babyId);return `<button class="baby-choice ${latest.id===b.id?'selected':''}" data-baby="${b.id}"><span style="background:${COLOURS[spec.colour]}">✦</span><div><strong>${esc(b.name)}</strong><small>Hatched ${formatDay(b.born)} · ${spec.rarity}</small></div></button>`;}).join('')}<div class="nursery-playcard"><span aria-hidden="true">☾ ✧ ♥</span><h3>A little routine, together.</h3><p>A berry, a cuddle, a word and a nap. Every baby stays happy when you’re away.</p><p>Teach words to build your baby’s own little word collection.</p></div></div></div>`:'<div class="empty-collection"><h3>A cosy nursery waiting for your first baby.</h3><p>Feed a berry, offer a cuddle, pop them into a cot, or practise a word together.</p><button class="secondary" id="demo-hatch-empty">See a baby hatch →</button></div>'}</section>`;}

function startMode(method){if(!METHODS[method]||!p().words.length){notify('Add this week’s spelling list first.');return;}selectedWord=null;if(['sentence','draw'].includes(method)){creativeWord=shuffle(p().words)[0].word;session={method};view='creative';}else{const items=orderedWords(p(),method);if(items.length>1&&items[0].word===lastStart)items.push(items.shift());lastStart=items[0]?.word;session={method,items,index:0,answer:'',feedback:'',answered:false,revealed:false,covered:false,built:[],letters:[],correct:0};view='game';}pendingQuestion=questionText();render();scrollTo({top:0,behavior:'smooth'});}
function gamePage(){if(session.finished)return finishPage();const m=METHODS[session.method],word=session.items[session.index],pr=p(),previous=pr.week.rounds[session.method],done=previous?.day===localDay()&&!previous.complete?previous.done.length:0;
 const choices=['gap','meaning'].includes(session.method),tiles=session.method==='build'||!choices&&pr.support==='tiles'&&['listen','study'].includes(session.method);
 if(!session.letters.length){session.letters=[...word.word].map((letter,id)=>({letter,id}));for(let i=session.letters.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[session.letters[i],session.letters[j]]=[session.letters[j],session.letters[i]];}}
 if(choices&&!session.choices)session.choices=choicesFor(pr,word.word);
 const study=session.method==='study'&&!session.covered&&!session.answered;
 const clue=session.method==='gap'?gapFor(word):session.method==='meaning'?word.meaning||'Ask a grown-up to describe this word.':'';
 return `<div class="activity-header"><button class="text-button" data-go="home">← My spelling list</button><strong>${m.title}</strong><span>${Math.min(pr.words.length,done+1)} / ${pr.words.length} weekly words</span></div><div class="activity-progress"><span style="width:${done/pr.words.length*100}%"></span></div><div class="game-layout"><section class="game-card" data-round-word="${esc(word.word)}">${session.nurseryBaby?`<div class="learning-baby">♥ ${esc((demoBaby||pr.babies.find(b=>b.id===session.nurseryBaby))?.name||'Baby')} is learning with you. A correct word teaches your baby too!</div>`:''}<span class="eyebrow">ONLY YOUR ${pr.words.length} WEEKLY SPELLINGS</span><h1>${{study:'Look. Say. Cover. Try.',listen:'Listen, then have a go.',build:'Build your weekly word.',letters:'What’s hiding in this word?',gap:'What’s the missing word?',meaning:'Which word matches?'}[session.method]}</h1>${choices?`<p class="question-clue">${esc(clue)}</p>`:session.method==='study'?`<div class="study-board ${session.covered&&!session.answered?'is-covered':''}"><div class="study-word" ${session.covered&&!session.answered?'aria-hidden="true"':''}>${esc(word.word)}</div><div class="word-cover" aria-hidden="true"><span>✋</span> Shhh… I’ve got it!</div></div><p class="word-meaning">${esc(word.meaning||'Say your word aloud with a grown-up.')}</p>`:session.method==='letters'?`<div class="masked-word">${esc([...word.word].map((ch,i)=>/[a-z]/.test(ch)&&i%3!==0?'_':ch).join(' '))}</div><p class="word-meaning">${esc(word.meaning||'Listen to the word, then fill in the letters.')}</p>`:session.method==='build'?`<p class="word-meaning">${esc(word.meaning||'Listen to the word, then arrange the letters.')}</p>`:'<p class="word-meaning">Listen as often as you like. Take your time.</p>'}<button class="listen-button" id="hear-word">♫ ${study?'Hear it':'Hear the word'}</button>${study?'<button class="primary cover-button" id="cover-word">I’ve looked. Cover it →</button>':session.answered?`<div class="revealed-word">${esc(word.word)}</div>`:choices?`<div class="answer-choices">${session.choices.map(w=>`<button data-answer="${esc(w)}">${esc(w)}</button>`).join('')}</div>`:tiles?`<div class="letter-slots">${session.built.map(id=>`<button data-remove="${id}">${esc(session.letters.find(x=>x.id===id).letter)}</button>`).join('')}${Array.from({length:Math.max(0,word.word.length-session.built.length)},()=>'<span>·</span>').join('')}</div><div class="letter-bank">${session.letters.map(x=>`<button data-letter="${x.id}" ${session.built.includes(x.id)?'disabled':''}>${esc(x.letter)}</button>`).join('')}</div>`:`<label class="field-label" for="answer">${session.method==='letters'?'Type the whole word':'Your spelling'}</label><input class="answer-input" id="answer" autocomplete="off" autocapitalize="off" spellcheck="false" value="${esc(session.answer)}" placeholder="Have a go…">`}<p class="feedback ${session.answered&&!session.revealed?'success':''}" id="feedback" role="status">${esc(session.feedback||'Trying is how we learn. I’m right here.')}</p><div class="game-buttons">${session.answered?`<button class="primary" id="next-word">${session.index===session.items.length-1?'Finish this round':'Next weekly word'} →</button>`:!study?`${!choices?'<button class="primary" id="check">Let’s check →</button>':''}<button class="text-button" id="show-word">Show me, then I’ll try again later</button>`:''}</div><p class="activity-note">This round covers the whole list. Leave whenever you need a break; completed words are saved for today.</p></section><aside class="game-companion">${palMarkup(pr,{prompt:session.feedback||({study:study?'Look at our word and say it with me.':'Can you spell it now it’s covered?',listen:'Can you spell the word I’m saying?',build:'Can you build my word with these letters?',letters:'Can you find my missing letters?',gap:'Can you choose the word missing from my sentence?',meaning:'Which weekly word matches my clue?'}[session.method])})}</aside></div>`;}
function bindGame(){if(session.finished)return;const word=session.items[session.index];$('#hear-word').onclick=()=>speak(questionText()||word.word);$('#cover-word')?.addEventListener('click',()=>{session.covered=true;pendingQuestion='Can you spell the word you just looked at?';render();});$('#answer')?.addEventListener('input',e=>session.answer=e.target.value);$('#answer')?.addEventListener('keydown',e=>{if(e.key==='Enter')checkAnswer();});$('#check')?.addEventListener('click',()=>checkAnswer());document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>checkAnswer(b.dataset.answer));document.querySelectorAll('[data-letter]').forEach(b=>b.onclick=()=>{session.built.push(Number(b.dataset.letter));render();});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{session.built=session.built.filter(x=>x!==Number(b.dataset.remove));render();});$('#show-word')?.addEventListener('click',()=>{session.answered=true;session.revealed=true;session.feedback='Here’s the word. Say its letters, then have another go next time.';recordWord(p(),word.word,session.method,{assisted:true});save();render();});$('#next-word')?.addEventListener('click',()=>{const result=completeWord(p(),word.word,session.method);save();session.index++;if(session.index>=session.items.length){session.finished=true;session.credited=result.credited;soundEffect('celebrate');}else Object.assign(session,{answer:'',answered:false,revealed:false,feedback:'',covered:false,built:[],letters:[],choices:null});pendingQuestion=session.finished?'You’ve practised your weekly words with me. Thank you for having a go!':questionText();render();const ready=p().eggs.find(e=>e.id===p().week.eggId);if(ready&&!ready.hatched&&eggProgress(ready).ready)beginHatch(ready.id);});}
function checkAnswer(choice){if(session.answered)return;const word=session.items[session.index],value=(choice??(session.method==='build'||p().support==='tiles'&&['listen','study'].includes(session.method)?session.built.map(id=>session.letters.find(x=>x.id===id).letter).join(''):session.answer)).trim().toLowerCase();if(!value){$('#feedback').textContent='Have a go, or ask for the word to be shown.';return;}const correct=value===word.word;recordWord(p(),word.word,session.method,{correct});save();if(correct){const learner=demoBaby?.id===session.nurseryBaby?demoBaby:p().babies.find(b=>b.id===session.nurseryBaby);if(learner){learner.learnedWords=[...new Set([...(learner.learnedWords||[]),word.word])];if(!demoBaby)save();}session.answered=true;session.correct++;session.feedback='Yes! '+(word.meaning||'You remembered your weekly word.');soundEffect('celebrate');}else session.feedback='A good try. Let’s listen again and try together.';pendingQuestion=session.feedback;render();}
function finishPage(){const pr=p(),available=Object.keys(WARDROBE).filter(x=>rewardAvailable(pr,x));return `<section class="finish-card"><span class="eyebrow">A LITTLE PRACTICE COUNTS</span><h1>${session.method==='draw'||session.method==='sentence'?'You made that word your own.':'You’ve worked through your whole list.'}</h1><p>${session.credited?'That’s another practice game towards your pal’s next wardrobe choice.':'More useful practice! This game already counted towards today’s wardrobe rewards.'}</p>${palMarkup(pr)}${available.length?`<div class="reward-callout"><strong>You’ve earned a ${available[0]} choice!</strong><button class="primary" data-go="pal">Choose something for my pal →</button></div>`:''}<div class="game-buttons"><button class="primary" data-go="home">Back to my weekly words →</button><button class="secondary" id="start-test">Try the whole-list test</button></div></section>`;}
function creativePage(){if(session.finished)return finishPage();const entry=p().words.find(x=>x.word===creativeWord)||p().words[0],draw=session.method==='draw';return `<div class="activity-header"><button class="text-button" data-go="home">← My spelling list</button><strong>${METHODS[session.method].title}</strong></div><section class="page-intro"><div><span class="eyebrow">CHOOSE ONLY FROM THIS WEEK’S WORDS</span><h1>${draw?'What does your word look like?':'Give your word a sentence.'}</h1></div><label class="profile-picker">My weekly word<select id="creative-word">${p().words.map(w=>`<option ${w.word===entry.word?'selected':''}>${esc(w.word)}</option>`).join('')}</select></label></section><div class="creative-layout"><section class="creative-card"><h2>${esc(entry.word)}</h2><p class="word-meaning">${esc(entry.meaning||'Talk about what this word means with a grown-up.')}</p>${draw?`<div class="drawing-tools">${['#70579b','#429784','#de876c','#4e8abb','#353343'].map((colour,i)=>`<button class="pen ${i===0?'chosen':''}" style="background:${colour}" data-pen="${colour}" aria-label="${['Purple','Green','Orange','Blue','Dark'][i]} pen"></button>`).join('')}<div class="draw-tool-row">${[['pen','✎ Pen'],['brush','▰ Brush'],['highlight','▱ Highlighter'],['eraser','▱ Rubber'],['star','★ Stamp'],['heart','♥ Stamp']].map(([key,label])=>`<button class="small-button ${key==='pen'?'chosen':''}" data-tool="${key}" aria-pressed="${key==='pen'}">${label}</button>`).join('')}<label>Size <input type="range" id="brush-size" min="3" max="50" value="8"></label><button class="small-button" id="undo-draw">↶ Undo</button><button class="small-button" id="redo-draw">↷ Redo</button><button class="text-button" id="clear-canvas">Clear</button></div></div><canvas id="drawing" width="900" height="560" aria-label="Draw a picture for your selected spelling word"></canvas>`:`<label class="field-label" for="sentence">Use “${esc(entry.word)}” in your own sentence</label><textarea id="sentence" rows="5" maxlength="350" placeholder="My sentence…"></textarea><button class="text-button" id="starter">Help me get started</button>`}<p class="feedback" id="creative-feedback" role="status">${draw?'Draw with a finger or mouse. Tell someone about your idea.':'A grown-up can help you talk about your sentence. Your pal doesn’t grade grammar.'}</p><button class="primary" id="save-creation">Keep it in my scrapbook →</button><button class="text-button" data-go="scrapbook">See my scrapbook</button></section><aside class="game-companion">${palMarkup(p(),{prompt:session.method==='draw'?'What could you draw to help us remember this word?':'Can you tell me a sentence using this word?'})}</aside></div>`;}
function containsWord(sentence,word){return sentence.toLowerCase().split(/[^a-z'-]+/).includes(word);}
function bindCreative(){if(session.finished)return;canvasDirty=false;$('#creative-word').onchange=e=>{creativeWord=e.target.value;pendingQuestion=questionText();render();};const canvas=$('#drawing');if(canvas)bindDrawing(canvas);$('#starter')?.addEventListener('click',()=>{$('#sentence').value='I noticed ';$('#sentence').focus();});$('#save-creation').onclick=()=>{const sentence=$('#sentence')?.value.trim()||'';if(session.method==='draw'&&!canvasDirty){$('#creative-feedback').textContent='Add a little drawing first.';return;}if(session.method==='sentence'&&!containsWord(sentence,creativeWord)){$('#creative-feedback').textContent=`Can you include “${creativeWord}” in your sentence?`;return;}p().scrapbook.unshift({word:creativeWord,method:session.method,sentence,image:canvasDirty?canvas.toDataURL('image/webp',.7):null,day:localDay()});p().scrapbook=p().scrapbook.slice(0,20);recordWord(p(),creativeWord,session.method,{correct:true});const result=completeWord(p(),creativeWord,session.method);session.finished=true;session.credited=result.credited;save();soundEffect('celebrate');render();};}
function scrapbookPage(){return `<section class="page-intro"><div><span class="eyebrow">WORDS YOU’VE MADE YOUR OWN</span><h1>Your spelling scrapbook.</h1><p>Your latest 20 pictures and sentences.</p></div><button class="secondary" data-go="home">My weekly words →</button></section><div class="scrapbook-grid">${p().scrapbook.length?p().scrapbook.map(x=>`<article class="scrapbook-card">${x.image?`<img src="${x.image}" alt="Your picture for ${esc(x.word)}">`:'<span class="sentence-art">Aa</span>'}<small>${formatDay(x.day)}</small><h2>${esc(x.word)}</h2><p>${esc(x.sentence||'Your own picture to remember this word.')}</p></article>`).join(''):'<p>Your first drawing or sentence will appear here.</p>'}</div>`;}

function startTest(){if(!p().words.length){notify('Add your weekly list first.');return;}test={items:shuffle(p().words).map(w=>({...w})),weekId:p().week.id,index:0,answers:[]};view='test';pendingQuestion=questionText();render();}
function testPage(){if(test.result){const r=test.result;return `<section class="finish-card"><span class="eyebrow">YOU GAVE THE WHOLE LIST A GO</span><h1>${r.score===r.total?'Every word. Well done!':'Look what you’re learning.'}</h1><strong class="test-score">${r.score} / ${r.total}</strong><p>${r.score===r.total?'That’s a full-mark practice test. Your hard work is showing.':'Try the tricky words again when you’re ready. No rush, and no lost rewards.'}</p><div class="test-results">${r.results.map(x=>`<div class="${x.correct?'correct':''}"><span>${x.correct?'✓':'↻'}</span><strong>${esc(x.word)}</strong><span>${x.correct?'Remembered!':`You wrote: ${esc(x.answer)}`}</span></div>`).join('')}</div><div class="game-buttons"><button class="primary" data-go="home">Back to my weekly words →</button><button class="secondary" data-go="egg">Check on my egg</button></div></section>`;}
return `<div class="activity-header"><button class="text-button" data-go="home">← Leave this test</button><strong>Whole-list practice test</strong><span>${test.index+1} / ${test.items.length}</span></div><div class="game-layout"><aside class="game-companion">${palMarkup(p(),{prompt:`Ready for word ${test.index+1}? Listen to me, then have a go.`})}</aside><section class="game-card test-card"><span class="eyebrow">ALL ${test.items.length} WORDS FROM YOUR WEEKLY LIST</span><h1>One word at a time.</h1><p>Listen, then spell it. We’ll check everything at the end.</p><button class="listen-button" id="hear-test">♫ Hear word ${test.index+1}</button><p class="hint">A grown-up can read word ${test.index+1} from your list if speech isn’t available.</p><label class="field-label" for="test-answer">My spelling</label><input id="test-answer" class="answer-input" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Have a go…"><p class="feedback" id="test-feedback" role="status">No hints. No timer. Just your own little try.</p><button class="primary" id="test-next">${test.index===test.items.length-1?'Finish my practice test':'Save and next word'} →</button></section></div>`;}
function bindTest(){if(test.result)return;$('#hear-test').onclick=()=>speak(questionText());const next=()=>{const answer=$('#test-answer').value.trim();if(!answer){$('#test-feedback').textContent='Have a go before moving on.';return;}test.answers.push(answer);test.index++;if(test.index===test.items.length){try{test.result=markTest(p(),test.answers,test.weekId,test.items.map(w=>w.word));save();soundEffect('celebrate');}catch(error){notify(error.message);go('home');return;}}pendingQuestion=test.result?'You gave the whole list a go! Well done for trying with me.':questionText();render();};$('#test-next').onclick=next;$('#test-answer').onkeydown=e=>{if(e.key==='Enter')next();};}

function voiceOptions(){const voices='speechSynthesis'in window?femaleEnglishVoices(speechSynthesis.getVoices()):[],chosen=chooseCalmVoice(voices,state.voiceURI);return voices.length?voices.map(v=>`<option value="${esc(v.voiceURI)}" ${chosen?.voiceURI===v.voiceURI?'selected':''}>${esc(v.name)} · ${esc(v.lang)}</option>`).join(''):'<option value="">No female English voice available yet</option>';}
if('speechSynthesis'in window)speechSynthesis.addEventListener('voiceschanged',()=>{if($('#voice-select'))$('#voice-select').innerHTML=voiceOptions();speakPending();});
function parentsPage(){if(!parentOpen)return `<section class="parent-gate"><span class="eyebrow">A LITTLE MOMENT FOR THE GROWN-UPS</span><h1>Set up this week.</h1><p>Add the actual spelling list, check the meanings and choose the school test date.</p><label class="field-label" for="gate">What is twelve plus seventeen?</label><input id="gate" inputmode="numeric"><p class="feedback" role="status">${esc(parentMessage)}</p><button class="primary" id="unlock">Open settings →</button><p class="hint">A simple settings check, not a password.</p></section>`;
const pr=p();return `<section class="page-intro"><div><span class="eyebrow">THE WEEKLY LIST IS THE WHOLE POINT</span><h1>This week, made simple.</h1><p>10 spellings for younger learners, or 15–20 for older children. Every game uses this list.</p></div>${profilePicker()}</section><section class="profile-settings"><label class="field-label">Child’s display name<input id="child-name" value="${esc(pr.name)}" maxlength="24"></label><label class="field-label">Age<select id="child-age">${[5,6,7,8,9,10].map(x=>`<option ${x===pr.age?'selected':''}>${x}</option>`).join('')}</select></label><label class="field-label">Spelling support<select id="support"><option value="type" ${pr.support!=='tiles'?'selected':''}>Type the word</option><option value="tiles" ${pr.support==='tiles'?'selected':''}>Letter tiles for hear & spell</option></select></label><button class="secondary" id="save-profile">Save profile</button></section><div class="parent-grid"><section class="settings-card"><h2>Your weekly spellings</h2><p>Your 15-word example is saved. One word per line, or separate words with commas. No extra spelling words are added to the games.</p>${pr.archivedLists?.length?'<button class="small-button" id="restore-list">Load my previous list into the editor</button>':''}<label class="field-label" for="words">This week’s list · up to 20 words</label><textarea id="words" rows="10" spellcheck="false">${esc(pr.words.map(w=>w.word).join('\n'))}</textarea><label class="field-label" for="test-date">School spelling-test date</label><input id="test-date" type="date" value="${pr.week?.testDate||nextTestDay()}"><p class="hint">The egg hatches when all words have six challenge lights. Editing a list keeps its current egg; start a new week to get a new egg.</p><div class="game-buttons"><button class="primary" id="save-week">Save list & suggest meanings →</button><button class="secondary" id="new-week">Start a new spelling week</button></div><p class="feedback" id="save-feedback" role="status"></p><p class="hint">Common meanings work offline. Other words use a dictionary lookup; only the word is sent. Review and edit suggestions before practice.</p><details><summary>Have a photo of the homework?</summary><p>Photo recognition isn’t connected yet. You can view a photo here and type its words above.</p><input id="homework-photo" type="file" accept="image/*" capture="environment">${photoUrl?`<img src="${photoUrl}" class="homework-photo" alt="Your homework sheet preview">`:''}</details><fieldset><legend>Your Practimal’s voice</legend><label class="checkbox-label"><input type="checkbox" id="spoken-questions" ${state.spokenQuestions!==false?'checked':''}> Let my Practimal ask the questions aloud</label><select id="voice-select">${voiceOptions()}</select><button class="secondary" id="preview-voice">♫ Preview voice</button><p class="hint">The child can choose Bubbles, Mallow or Ziggle in My pal. These are pitched, playful styles of a device female English voice, rather than recordings. This selector sets the base voice. No male fallback. If none are available, enable a female English voice in the tablet’s settings.</p></fieldset></section><section class="settings-card"><h2>Simple meanings, your words</h2><p>Edit any suggestion to match your child’s age and the meaning used at school.</p><div class="meaning-list">${pr.words.map((w,i)=>`<article class="meaning-editor"><h3>${esc(w.word)}</h3><small>${esc(w.meaningSource||'Parent meaning')}${w.meaningAttribution?` · <a href="${esc(w.meaningAttribution)}" target="_blank" rel="noopener noreferrer">Source</a>`:''}${w.meaningLicense?` · ${esc(w.meaningLicense)}`:''}</small><label class="field-label">Simple meaning<input data-meaning="${i}" maxlength="250" value="${esc(w.meaning||'')}" placeholder="Explain the word simply…"></label><label class="field-label">Example sentence using the word<input data-example="${i}" maxlength="250" value="${esc(w.sentence||'')}" placeholder="Used in the missing-word game"></label></article>`).join('')||'<p>Add a list to see the meaning suggestions here.</p>'}</div><button class="secondary" id="save-meanings">Save meanings & sentences</button></section></div>${schoolResultsPanel()}<section class="parent-notes"><h2>What counts as practice?</h2><p>The six spelling and meaning games work through the whole list. Children can pause and resume the remaining words that day. Sentence and drawing activities focus on one chosen weekly word. A completed game counts once per method per day towards a hat after 1 game, a coat after 3 shoes after 5, glasses after 7, gloves after 9 and earrings after 11 lifetime games. Colours continue up to rainbow at 24 games. Creative work is recorded as a try, not automatically graded.</p><p>All six core challenges must be answered correctly for a word to turn green. Showing an answer is useful practice but does not earn that challenge light. All words green unlocks the hatch. School test dates never control the egg. The whole-list practice test is available whenever the child wants to try it.</p><p>Progress, clothes, drawings and babies save on this device only. There are no school accounts or cloud sync.</p><button class="text-button" data-go="scrapbook">View the scrapbook →</button></section>`;}
function saveEditor(){document.querySelectorAll('[data-meaning]').forEach(el=>p().words[Number(el.dataset.meaning)].meaning=el.value.trim());document.querySelectorAll('[data-example]').forEach(el=>p().words[Number(el.dataset.example)].sentence=el.value.trim());}
function bindParents(){if(!parentOpen){const unlock=()=>{if($('#gate').value.trim()==='29'){parentOpen=true;parentMessage='';render();}else{parentMessage='Try that little sum again.';render();}};$('#unlock').onclick=unlock;$('#gate').onkeydown=e=>{if(e.key==='Enter')unlock();};return;}$('#save-profile').onclick=()=>{p().name=$('#child-name').value.trim()||'My spellings';p().age=Number($('#child-age').value);p().support=$('#support').value;save();notify('Profile saved.');render();};const saveWeek=async newWeek=>{const active=p();let words;try{words=parseWeeklyWords($('#words').value);}catch(error){$('#save-feedback').textContent=error.message;return;}const date=$('#test-date').value;if(!words.length){$('#save-feedback').textContent='Add at least one spelling first.';return;}if(!date){$('#save-feedback').textContent='Choose the school spelling-test date.';return;}saveEditor();$('#save-week').disabled=true;$('#new-week').disabled=true;$('#save-feedback').textContent='Finding simple meaning suggestions…';const suggestions=await suggestWordList(words,[...active.words,...(active.archivedLists||[]).flatMap(a=>a.words)]);try{setWeek(active,suggestions,date,{newWeek});save();if(view==='parents'&&active===p()){selectedWord=null;render();notify('This week’s list is ready. Check the suggested meanings.');}}catch(error){if($('#save-feedback'))$('#save-feedback').textContent=error.message;if($('#save-week'))$('#save-week').disabled=false;if($('#new-week'))$('#new-week').disabled=false;}};$('#save-week').onclick=()=>saveWeek(false);$('#new-week').onclick=()=>saveWeek(true);$('#save-meanings').onclick=()=>{saveEditor();save();notify('Meanings and example sentences saved.');};$('#spoken-questions').onchange=e=>{state.spokenQuestions=e.target.checked;save();};$('#voice-select').onchange=e=>{state.voiceURI=e.target.value;save();};$('#preview-voice').onclick=()=>speak('Hello. Take your time. Let’s practise a word together.');$('#homework-photo').onchange=e=>{const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>10000000){notify('Choose a photo smaller than 10 MB.');return;}if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl=URL.createObjectURL(file);const image=document.createElement('img');image.src=photoUrl;image.alt='Your homework sheet preview';image.className='homework-photo';$('#homework-photo').parentElement.querySelector('.homework-photo')?.remove();$('#homework-photo').parentElement.append(image);};}
function bindCommon(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=e=>{e.preventDefault();go(b.dataset.go);});$('#profile')?.addEventListener('change',e=>{state.active=e.target.value;selectedWord=null;save();render();});$('#sound').onclick=()=>{state.sound=!state.sound;save();render();};document.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>startMode(b.dataset.method));document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{selectedWord=selectedWord===b.dataset.word?null:b.dataset.word;render();});document.querySelectorAll('[data-hear]').forEach(b=>b.onclick=()=>speak(b.dataset.hear));$('#hear-all')?.addEventListener('click',()=>speak(p().words.map(x=>x.word).join('. ')));$('#save-pal-name')?.addEventListener('click',()=>{p().palName=$('#pal-name').value.trim()||'Bobble';save();render();});document.querySelectorAll('[data-shape]').forEach(b=>b.onclick=()=>{p().species=b.dataset.shape;save();render();});document.querySelectorAll('[data-colour]').forEach(b=>b.onclick=()=>{if(canUseColour(p(),b.dataset.colour)){p().colour=b.dataset.colour;save();render();}});document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{if(chooseClothes(p(),b.dataset.category,b.dataset.claim)){save();soundEffect('celebrate');render();notify('Your choice is yours to keep!');}});document.querySelectorAll('[data-wear]').forEach(b=>b.onclick=()=>{if(equip(p(),b.dataset.category,b.dataset.wear==='none'?null:b.dataset.wear)){save();render();}});document.querySelectorAll('[data-hatch]').forEach(b=>b.onclick=()=>beginHatch(b.dataset.hatch));document.querySelectorAll('[data-baby]').forEach(b=>b.onclick=()=>{demoBaby=null;chosenBaby=b.dataset.baby;render();});$('#start-test')?.addEventListener('click',startTest);}
render();

function methodArt(key){const shapes={study:'<rect x="14" y="19" width="54" height="47" rx="9"/><path d="M22 34h28M22 43h21M48 23l15 40"/>',listen:'<path d="M18 46v-9a23 23 0 0146 0v9M18 38h8v22h-8zM56 38h8v22h-8zM34 35v20l17-10z"/>',build:'<rect x="9" y="16" width="26" height="28" rx="6"/><rect x="42" y="23" width="26" height="28" rx="6"/><rect x="25" y="49" width="26" height="25" rx="6"/><path d="M20 24v12M48 34h13M33 60h9"/>',letters:'<path d="M16 55l10-28 10 28M20 45h12M45 52h11M65 30v25M60 42h10"/><circle cx="51" cy="30" r="5"/>',gap:'<path d="M12 24h54M12 39h20M12 55h54"/><rect x="40" y="32" width="28" height="14" rx="4"/>',meaning:'<path d="M12 17h47v35H38L23 66V52H12zM37 27c14-7 18 7 7 11v5M43 48h1"/>',sentence:'<path d="M15 61l6-19 33-29 13 13-33 29zM21 42l13 13M15 61l19-6M48 19l13 13"/>',draw:'<path d="M25 51l25-34 14 10-25 34zM25 51c-21 2-7 20-15 19 16 4 24-1 29-9M49 21l13 9"/><circle cx="19" cy="23" r="7"/>'};return `<svg viewBox="0 0 80 80" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round">${shapes[key]}</svg>`;}
function schoolResultsPanel(){const pr=p();return `<section class="settings-card school-records"><span class="eyebrow">THE REAL SCHOOL TEST</span><h2>How did the school test go?</h2><p>Record the result for this week’s list. Tick words that need another go. Leave every box clear for full marks.</p><label class="field-label">Actual test date<input type="date" id="actual-date" value="${pr.week?.testDate||localDay()}"></label><fieldset><legend>Words that were wrong</legend><div class="wrong-word-grid">${pr.words.map(w=>`<label><input type="checkbox" data-wrong-word="${esc(w.word)}"> ${esc(w.word)}</label>`).join('')}</div></fieldset><label class="field-label">Notes (optional)<textarea id="actual-notes" maxlength="500" rows="2"></textarea></label><button class="primary" id="save-actual">Save school test result</button><p id="actual-feedback" class="feedback" role="status"></p><div class="school-history">${(pr.schoolResults||[]).map(r=>`<article><strong>${formatDay(r.date)} · ${r.score}/${r.total}</strong><p>${r.wrongWords.length?'Practise again: '+r.wrongWords.map(esc).join(', '):'All words correct!'}</p>${r.notes?`<p>${esc(r.notes)}</p>`:''}</article>`).join('')||'<p>Your school test records will stay here across spelling weeks.</p>'}</div></section>`;}
function beginHatch(id,demo=false){if(!demo){syncEgg(p());const egg=p().eggs.find(e=>e.id===id);if(!egg||egg.hatched||!eggProgress(egg).ready)return;}hatchScene={id,demo,step:0,babyId:demo?'nova':p().eggs.find(e=>e.id===id).babyId};view='hatching';pendingQuestion='I can hear a little wiggle! Shall we meet our baby?';render();soundEffect('travel');scrollTo({top:0,behavior:'smooth'});}
function hatchingPage(){if(!hatchScene)return eggPage();const h=hatchScene,baby=BABIES.find(b=>b.id===h.babyId);return `<section class="hatch-scene hatch-step-${h.step}"><span class="eyebrow">${h.demo?'HATCH PREVIEW · NO REAL PROGRESS CHANGED':'YOU LIT EVERY WORD GREEN'}</span><h1>${['Did you hear that little wiggle?','A crack… and a tiny squeak!','Hello, little '+baby.name+'!'][h.step]}</h1><div class="hatch-stage">${h.step<2?eggSVG({steps:h.step?85:65,total:90}):`<div class="hatch-confetti" aria-hidden="true">✦ ✧ ♥ ✦ ✧</div>${palMarkup({...baby,palName:baby.name,wearing:{}},{baby:true})}`}</div><p>${['Your practice has helped a new little friend grow. Tap the button to help it hatch.','Someone is pushing their way out. One more little wiggle…','A '+baby.rarity.toLowerCase()+' baby to feed, cuddle and tuck into a cosy cot.'][h.step]}</p><button class="primary" id="hatch-step">${['Give it a little wiggle ✧','Meet our baby →','Take me to the nursery →'][h.step]}</button><button class="text-button" data-go="egg">${h.demo?'Close preview':'Come back in a moment'}</button></section>`;}
function bindV5(){$('[data-teach-baby]')?.addEventListener('click',()=>{const b=demoBaby||p().babies.find(x=>x.id===chosenBaby)||p().babies.at(-1);if(!b)return;startMode('listen');session.nurseryBaby=b.id;render();});document.querySelectorAll('[data-eyes]').forEach(b=>b.onclick=()=>{p().eyeColour=b.dataset.eyes;save();render();});document.querySelectorAll('[data-voice-style]').forEach(b=>b.onclick=()=>{p().voiceStyle=b.dataset.voiceStyle;save();render();speak('Hello! I’m '+p().palName+'. Shall we practise together?');});for(const id of ['demo-hatch','demo-hatch-empty'])$('#'+id)?.addEventListener('click',()=>beginHatch(null,true));$('#close-demo')?.addEventListener('click',()=>{demoBaby=null;render();});$('#hatch-step')?.addEventListener('click',()=>{if(hatchScene.step<2){hatchScene.step++;render();soundEffect(hatchScene.step===2?'celebrate':'travel');return;}const h=hatchScene;if(h.demo)demoBaby={id:'preview-only',babyId:h.babyId,name:'Nova',care:{feeds:0,cuddles:0,asleep:false}};else if(hatchEgg(p(),h.id)){chosenBaby=p().babies.at(-1).id;save();}hatchScene=null;view='egg';render();document.querySelector('.baby-display')?.scrollIntoView({behavior:'smooth',block:'center'});});document.querySelectorAll('[data-care]').forEach(b=>b.onclick=()=>{const baby=demoBaby||p().babies.find(x=>x.id===chosenBaby)||p().babies.at(-1);if(!baby||!careForBaby(baby,b.dataset.care))return;if(!demoBaby)save();render();const status=$('.care-status');if(status)status.textContent={feed:'Nom nom! A lovely berry. Happy little tummy.',cuddle:'A warm snuggle. You are a lovely little friend.',cot:baby.care.asleep?'Tucked into the cot. Zzz…':'Good morning, little one!'}[b.dataset.care];if(b.dataset.care==='cuddle')$('.baby-display [data-pal-action=purr]')?.click();if(b.dataset.care==='feed'){const snack=document.createElement('span');snack.className='care-snack';snack.textContent='🍓';snack.setAttribute('aria-hidden','true');$('.baby-display .pal-stage')?.append(snack);$('.baby-display [data-pal-action=giggle]')?.click();}});$('#save-actual')?.addEventListener('click',()=>{try{const r=recordSchoolTest(p(),{date:$('#actual-date').value,wrongWords:[...document.querySelectorAll('[data-wrong-word]:checked')].map(el=>el.dataset.wrongWord),notes:$('#actual-notes').value});save();render();$('#actual-feedback').textContent='Saved: '+r.score+' of '+r.total+'.';}catch(e){$('#actual-feedback').textContent=e.message;}});$('#restore-list')?.addEventListener('click',()=>{$('#words').value=p().archivedLists.at(-1).words.map(w=>w.word).join('\n');notify('Previous words loaded into the editor. Save the list when you’re ready.');});}
function bindDrawing(canvas){const ctx=canvas.getContext('2d');let pen='#70579b',tool='pen',size=8,history=[],future=[];const snapshot=()=>({image:ctx.getImageData(0,0,canvas.width,canvas.height),dirty:canvasDirty});const remember=()=>{history.push(snapshot());if(history.length>20)history.shift();future=[];buttons();};const buttons=()=>{$('#undo-draw').disabled=!history.length;$('#redo-draw').disabled=!future.length;};const restore=data=>{ctx.putImageData(data.image,0,0);canvasDirty=data.dirty;};const point=e=>{const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.x)/r.width*canvas.width,y:(e.clientY-r.y)/r.height*canvas.height};};const brush=()=>{ctx.globalCompositeOperation=tool==='eraser'?'destination-out':'source-over';ctx.globalAlpha=tool==='highlight'?.28:1;ctx.strokeStyle=pen;ctx.fillStyle=pen;ctx.lineWidth=tool==='brush'?size*2:tool==='eraser'?size*3:tool==='highlight'?size*3:size;ctx.lineCap='round';ctx.lineJoin='round';};canvas.onpointerdown=e=>{e.preventDefault();remember();canvas.setPointerCapture(e.pointerId);const q=point(e);canvasDirty=true;brush();if(['star','heart'].includes(tool)){ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;ctx.font=(size*4+24)+'px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(tool==='star'?'★':'♥',q.x,q.y);return;}drawing=true;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(q.x+.1,q.y+.1);ctx.stroke();};canvas.onpointermove=e=>{if(!drawing)return;const q=point(e);ctx.lineTo(q.x,q.y);ctx.stroke();};canvas.onpointerup=canvas.onpointercancel=()=>{drawing=false;ctx.globalAlpha=1;};document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.tool;document.querySelectorAll('[data-tool]').forEach(el=>{el.classList.toggle('chosen',el===b);el.setAttribute('aria-pressed',el===b);});});document.querySelectorAll('[data-pen]').forEach(b=>b.onclick=()=>{pen=b.dataset.pen;document.querySelectorAll('[data-pen]').forEach(el=>el.classList.toggle('chosen',el===b));});$('#brush-size').oninput=e=>size=+e.target.value;$('#undo-draw').onclick=()=>{if(!history.length)return;future.push(snapshot());restore(history.pop());buttons();};$('#redo-draw').onclick=()=>{if(!future.length)return;history.push(snapshot());restore(future.pop());buttons();};$('#clear-canvas').onclick=()=>{remember();ctx.clearRect(0,0,canvas.width,canvas.height);canvasDirty=false;};buttons();}
